'use strict';
(()=>{
const G=window.Qingchuan,A=window.CityArt,$=id=>document.getElementById(id),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='qingchuan-demo-v5';let s,saveOK=true,previousFocus=null,toastTimer,walker=null,near=null,auto=null,autoTimer=null,nudgeTimer=null;const seed=()=>{const a=new Uint32Array(1);crypto.getRandomValues(a);return a[0];};
try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw&&raw.version===G.VERSION&&raw.voters?.length===G.POPULATION&&raw.day>=1&&raw.day<=5&&Array.isArray(raw.polls)&&raw.done&&['cash','campaign','energy','debt','lifeLeft'].every(k=>Number.isFinite(raw[k])))s=raw;}catch{saveOK=false;}if(!s)s=G.initial(seed());else G.upgrade(s);
const avatar=(species,color)=>A.avatar(species,color),time=n=>n+' 格時間',signed=n=>(n>0?'+':'')+n,placeName=id=>G.LOCS.find(l=>l.id===id)?.name||'路上';
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));saveOK=true;}catch{saveOK=false;}$('save-status').textContent=saveOK?'本機自動存檔 · 自由行動版':'無法存檔 · 關閉頁面會失去進度';}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2600);}
function modal(title,body,wide=false,canClose=true){clearTimeout(nudgeTimer);nudgeTimer=null;walker?.stop();clearTimeout(autoTimer);if(auto){auto.paused=true;autoStatus();}if($('modal-overlay').hidden)previousFocus=document.activeElement;$('modal').className='modal'+(wide?' wide':'');$('modal').innerHTML=(canClose?'<button class="modal-close" data-do="close" aria-label="關閉">×</button>':'')+'<h2 id="modal-title">'+title+'</h2>'+body;$('modal-overlay').hidden=false;$('game').inert=true;document.querySelector('.topbar').inert=true;$('modal').focus();}
function close(){if(!s.started)return;$('modal-overlay').hidden=true;$('game').inert=false;document.querySelector('.topbar').inert=false;walker?.focus();}
function speaker(id){const p=G.NPC[id];return '<div class="speaker"><div class="portrait">'+avatar(p.species)+'</div><div><b>'+p.name+'</b><small>'+p.role+'</small></div></div>';}
function eventAt(id){return Object.values(G.EVENTS).find(e=>e.loc===id&&G.available(s,e.id));}
function updateNear(n){near=n;const l=n&&G.LOCS.find(l=>l.id===n.id);s.location=l?l.id:'street';$('location-hint').textContent=l?'E / Enter · '+l.name+'，看看能做什麼':'↑ ↓ ← → / WASD 走路 · 靠近地點按 E';$('location-hint').disabled=!l;$('near-marker').hidden=!l;if(l){const p=A.positions[l.id];$('near-marker').style.left=p.ax+'%';$('near-marker').style.top=p.ay+'%';}$('story-btn').textContent=l?'在'+l.name+'互動 ↗':'選一個地方前往 ↗';}
function autoStatus(){$('auto-stop').hidden=!auto;$('auto-btn').textContent=auto?(auto.paused?'繼續已安排的日常':'自動日常進行中…'):'安排自動一天';$('auto-note').textContent=auto?(auto.paused?'已暫停。新增承諾與取捨等你決定。':'只執行已選日常；方向鍵或停止可立刻接手。'):'你選優先事項；新事件會停下，等你決定。';}
function render(){const ended=s.phase==='result',p=s.polls.at(-1);$('day-label').textContent='第 '+s.day+' 天 / 5';$('day-heading').textContent=ended?'開票了。生活，也還要繼續。':'今天去哪裡，由你自己選。';$('day-subtitle').textContent=ended?'選票、生計與承諾，放在一起回頭看。':G.originOf(s).name+' · 知名度 '+Math.round(s.recognition)+' / 100 · '+(s.dailyEvent?.title||'第一次參選，還沒多少人認識你')+' · 走路不扣時間，做事才扣。';$('time-label').textContent=ended?'票數固定，可同條件重玩':'剩 '+s.lifeLeft+' / 4 格時間';for(const k of ['energy','mood']){$(k+'-value').textContent=s[k];$(k+'-bar').style.width=s[k]+'%';}$('cash-value').textContent=s.cash.toLocaleString();$('campaign-value').textContent=s.campaign.toLocaleString();$('cash-note').textContent=s.debt?'未付生活帳單 '+s.debt:ended?'房租已結清':'第 4 天房租 700';$('poll-value').textContent=p?'約 '+p.percent+'%':'—';$('poll-note').textContent=p?'第 '+p.day+' 天 · n=48 · 含未決':'開局後產生當日樣本';
$('map-locations').innerHTML=G.LOCS.map(l=>{const p=A.positions[l.id],ev=eventAt(l.id);return '<button class="location '+(ev?'story':'')+'" style="left:'+p.x+'%;top:'+p.y+'%" data-place="'+l.id+'">'+l.name+'<span class="loc-dot">!</span></button>';}).join('');const people=[{id:'yun',loc:'market',name:'阿芸',species:'turtle',color:'#bdab79'},{id:'an',loc:'hall',name:'季安',species:'bear',color:'#78919b'},{id:'ye',loc:'school',name:'小葉',species:'rabbit',color:'#c69e76'}];$('map-people').innerHTML=people.map((p,i)=>{const xy=A.positions[p.loc];return '<div class="npc-piece" style="left:'+(xy.ax+(i===0?-3:3))+'%;top:'+(xy.ay-1)+'%"><span>'+p.name+'</span>'+avatar(p.species,p.color)+'</div>';}).join('')+G.RIVALS.map((r,i)=>{const item=s.rivalLog.filter(x=>x.id===r.id).at(-1),p=A.positions[item?.loc||'park'];return '<div class="npc-piece rival-piece" style="left:'+(p.ax+(i===0?8:-7))+'%;top:'+(p.ay+3)+'%"><span>'+r.name+'<small class="npc-role"> · 對手</small></span>'+avatar(r.species,r.color)+'</div>';}).join('');
$('chapter-label').textContent=ended?'05 / 選票之後':'自由行動 / 沒有必答的今日題目';$('story-title').textContent=ended?'這幾天，留下了什麼？':s.lifeLeft?'工作、拜訪，或喘口氣？':'今天的時間已經用完。';$('story-status').textContent=ended?'投票結果':s.lifeLeft+' 格';const obligations=[];if(s.originObligation?.status==='pending')obligations.push('第 '+s.originObligation.due+' 天前，'+s.originObligation.text);if(s.obligation==='pending')obligations.push('第 '+s.obligationDue+' 天前，赴季安的約');if(s.loan?.status==='pending')obligations.push('第 '+s.loan.due+' 天前，完成借用設備的整理約定');$('story-summary').textContent=ended?s.summary.reflection:(obligations.length?'待辦：'+obligations.join('；')+'。':s.dailyEvent?.text||'市場可接班、學院可整理資料、討論所可談合作。你不必把每件事都做完。');$('story-btn').textContent=ended?'看開票與回顧 ↗':near?'在'+placeName(near.id)+'互動 ↗':'選一個地方前往 ↗';$('life-time').textContent=ended?'已結束':time(s.lifeLeft);$('time-slots').innerHTML=[0,1,2,3].map(i=>'<i class="'+(i>=s.lifeLeft?'spent':'')+'"></i>').join('');$('life-note').textContent=ended?'選戰結束，但生活並沒有暫停。':'每格是一段壓縮行程。談合作、接班、查證會互相排擠；四種故事可以不做，也能換順序。';$('life-btn').textContent='看看各地能做什麼';$('life-btn').disabled=ended;$('people').innerHTML=Object.entries(G.NPC).map(([id,p])=>'<div class="person"><div class="portrait">'+avatar(p.species)+'</div><div class="person-info"><b>'+p.name+'</b><small>'+p.role+'</small><p>'+esc(s.reactions[id]||p.line)+'</p></div></div>').join('');$('rivals').innerHTML=G.RIVALS.map((r,i)=>{const last=s.rivalLog.filter(x=>x.id===r.id).at(-1);return '<div class="rival-row"><b>'+r.name+' <span>約 '+(p?.percentages[i+1]??'—')+'%</span></b><small>'+r.tag+'</small><p>'+esc(last?.text||r.intro)+'</p></div>';}).join('')+'<small class="poll-foot">你約 '+(p?.percent??'—')+'% · 未決約 '+(p?.percentages[3]??'—')+'%<br>同一份每日固定樣本，非即時加減票。</small>';$('end-day-btn').disabled=!s.started;$('end-day-btn').classList.toggle('ready',!s.lifeLeft||ended);$('end-day-btn').querySelector('b').textContent=ended?'回看選票與生活':'回家，結束今天';$('end-day-help').textContent=ended?'選過與沒選的事，都留下了痕跡':s.day===4?'今晚生活費 −80、房租 −700':'今晚生活費 −80';$('journal-count').textContent=s.journal.length;$('character-thought').textContent=s.energy<25?'「身體真的累了。也可以先休息。」':s.recognition<30?'「我還不有名，今天要把時間用在哪裡？」':'「有人開始認識我，也開始問起說過的話。」';autoStatus();save();}
function intro(){const o=G.originOf(s);modal('從哪一種起點，走進選戰？','<div class="intro-art"><div class="portrait">'+avatar('fox')+'</div><div class="intro-copy">同一個阿夏。<br>起點不同，選擇仍是你的。</div></div><p>選一個背景，或讓本局種子替你抽一次。背景決定起始資源與既有約定，不替你決定個性、政見或結局。</p><div class="choices origin-choices">'+Object.values(G.ORIGINS).map(x=>'<button class="choice '+(s.origin===x.id?'origin-selected':'')+'" data-origin="'+x.id+'"><b>'+(s.origin===x.id?'● ':'○ ')+x.name+' · '+x.tag+'</b><span class="desc">生活現金 '+x.cash+'／競選額度 '+x.campaign+'／知名度 '+x.recognition+'<br>'+x.description+'<br>'+x.constraint+'</span></button>').join('')+'</div><button class="secondary-button full origin-random" data-origin="random">🎲 隨機抽背景（本局固定，不會連按重抽）</button><div class="notice">'+(s.originSelection==='random'?'這次抽到：':'目前選擇：')+'<strong>'+o.name+'</strong>。每天 4 格時間；生活費 80，最後房租 700。競選資源不能付房租。</div><p>↑ ↓ ← →／WASD 走路，靠近按 E 或 Enter。點地點也能自動走；普通日常可自動，重大選擇停下等你。四類故事可跳過與換順序，第五天開票。</p><p class="modal-note">完全虛構的動物小城、政黨與數字。先前正在玩的 v5 存檔會繼續，不重新發資源或重抽起點；舊版本存檔仍保留。</p><button class="primary-button" data-do="start">以「'+o.name+'」出門 →</button>',true,false);}
function travel(id,callback){if(!s.started)return;close();const ok=walker.goTo(id,()=>{s.location=id;s.position=walker.getPosition();save();(callback||(()=>place(id)))();});if(!ok)toast('這條路暫時走不到，請用方向鍵靠近地點。');}
function destinations(){if(s.phase==='result')return finalResult();modal('先去哪裡？','<p>點地點會自動走過去，也可以關閉後用方向鍵自己走。走路不扣時間。</p><div class="choices">'+G.LOCS.map(l=>'<button class="choice" data-place="'+l.id+'"><b>'+l.name+'</b><span class="desc">'+(eventAt(l.id)?eventAt(l.id).name+'；':'')+G.actions(s,l.id).map(c=>c.title).join('、')+'</span></button>').join('')+'</div>');}
function place(id){if(s.phase==='result')return finalResult();if(!near||near.id!==id){travel(id);return;}s.location=id;const l=G.LOCS.find(x=>x.id===id),ev=eventAt(id),enc=G.encounter(s,id),acts=G.actions(s,id);modal(l.name,'<p class="eyebrow">'+l.kind+' · 剩 '+s.lifeLeft+' 格時間</p><p>'+l.desc+'</p>'+(ev?'<button class="choice event-choice" data-story="'+ev.id+'"><b>和'+G.NPC[ev.npc].name+'聊聊：'+ev.name+'</b><span class="desc">先看選項，沒有選就不扣時間。可以離開，不必現在決定。</span></button>':'')+(enc?'<button class="choice event-choice" data-encounter="'+id+'"><b>臨時插曲：'+enc.title+'</b><span class="desc">這件事由本局種子與日期固定；離開再回來不會重抽。</span></button>':'')+'<div class="choices">'+acts.map(c=>'<button class="choice" data-act="'+c.id+'" '+(!G.canAction(s,c)?'disabled':'')+'><b>'+c.title+'</b><span class="desc">'+c.desc+'</span><span class="effects"><span class="effect cost">'+time(c.time)+'</span><span class="effect cost">精神 '+signed(c.energy||0)+'</span>'+(c.cash?'<span class="effect cost">生活現金 '+signed(c.cash)+'</span>':'')+(c.campaign?'<span class="effect cost">競選額度 −'+c.campaign+'</span>':'')+(c.withdrawal?'<span class="effect cost">另撤回未用聯名額度 −'+c.withdrawal+'</span>':'')+(!G.canAction(s,c)?'<span class="effect cost">時間／體力／資源不足</span>':'')+'</span></button>').join('')+'</div>'+(auto?'<div class="button-row"><button class="secondary-button" data-do="close">先自己走走</button><button class="primary-button" data-do="auto-resume">先做已排定的日常 →</button></div>':'<p class="modal-note">這裡沒有必答題。剩下的時間，你可以去別處。</p>'),true);}
function story(event){if(!G.available(s,event))return;const sc=G.scene(s,event);if(s.location!==sc.loc)return travel(sc.loc,()=>story(event));modal(sc.title,'<p class="eyebrow">'+placeName(sc.loc)+' · 自由選擇的事件</p><p>'+sc.intro+'</p>'+speaker(sc.npc)+'<div class="quote">'+sc.quote+'</div><div class="choices">'+sc.choices.map(c=>'<button class="choice" data-decide="'+c.id+'" data-event="'+event+'" '+(!G.canDecide(s,c.id,event)?'disabled':'')+'><b>'+String.fromCharCode(65+c.id)+' · '+c.title+'</b><span class="desc">'+c.desc+'</span><span class="effects"><span class="effect cost">'+time(c.time)+'</span><span class="effect cost">精神 −'+c.energy+'</span><span class="effect cost">競選額度 −'+c.campaign+'</span>'+(c.withdrawal?'<span class="effect cost">另撤回未用聯名額度 −'+c.withdrawal+'</span>':'')+'</span></button>').join('')+'</div><p class="modal-note">先列確定成本，不列固定加票。沒有足夠時間，也可以改天再來；你不必把四件事都做完。</p>',true);}
function result(r){render();modal('這個選擇，留下了什麼？','<p class="eyebrow">'+esc(r.title)+'</p><p>'+r.result+'</p>'+Object.entries(r.reactions||{}).map(([id,t])=>'<div class="reaction"><strong>'+G.NPC[id].name+'：</strong>'+esc(t)+'</div>').join('')+(r.before?'<div class="receipt"><span>生活現金 '+signed(r.after.cash-r.before.cash)+'</span><span>競選額度 '+signed(r.after.campaign-r.before.campaign)+'</span><span>精神 '+signed(r.after.energy-r.before.energy)+'</span><span>剩 '+s.lifeLeft+' 格</span></div>':'')+(r.encounter?'<div class="callback"><b>有人叫住你：'+esc(r.encounter.title)+'</b><p>這是剛才行動後出現的插曲。可以看看，也可以先離開；沒有替你答應。</p><button class="primary-button" data-encounter="'+r.encounter.loc+'">看看發生什麼 →</button></div>':'')+'<p class="modal-note">民調等下一個早晨才更新。這些是眼前的代價與個別回應，不是每題的得票分數。</p><div class="button-row"><button class="secondary-button" data-do="close">回小城，自己走</button><button class="primary-button" data-do="'+(auto?'auto-resume':s.lifeLeft?'destinations':'end')+'">'+(auto?'繼續已安排的日常':s.lifeLeft?'看看其他地方':'結束今天')+' →</button></div>',true);}
function perform(id,automated=false){const c=G.act(s,id);if(!c)return;render();const e=G.encounter(s,s.location);if(automated){toast(c.title+' · 剩 '+s.lifeLeft+' 格');if(e){auto.paused=true;showEncounter(s.location);return;}autoTimer=setTimeout(autoStep,900);}else result({title:c.title,result:c.result,reactions:c.reactions,encounter:e?{title:e.title,loc:s.location}:null});}
function showEncounter(loc){const e=G.encounter(s,loc);if(!e)return;modal(e.title,'<p>'+e.text+'</p><div class="choices">'+e.choices.map(c=>'<button class="choice" data-enc-choice="'+c.id+'" data-enc-loc="'+loc+'" '+(s.lifeLeft<c.time||s.energy+c.energy<0?'disabled':'')+'><b>'+c.title+'</b><span class="desc">'+c.desc+'</span></button>').join('')+'</div><p class="modal-note">這是今天固定的一次插曲，不因走路速度、重讀或離開再回來改變。</p>');}
function stopAuto(message=true,preserveWalk=false){clearTimeout(autoTimer);auto=null;if(!preserveWalk)walker?.stop();autoStatus();if(message)toast('已停止自動日常；已做的事保留，接下來由你控制。');}
function autoConfig(){if(auto)return resumeAuto();if(s.phase!=='play')return;modal('把普通日常交給行程表。','<p>只安排今天剩下的時間，走到地方再做事。遇到新故事或臨時交換會停下，等你決定；不替你選政見、不新增承諾。</p><div class="choices"><button class="choice" data-auto="work"><b>先補生活費</b><span class="desc">能上完整班就接班，不夠體力先休息；只剩一格就接短班。只把收入放進生活現金。</span></button><button class="choice" data-auto="promise"><b>先赴已答應的約，再休息</b><span class="desc">有未完成的共同整理便先去；不會替你答應新邀請，之後去公園恢復體力。</span></button><button class="choice" data-auto="rest"><b>今天先照顧自己</b><span class="desc">把剩餘時間用來免費休息，不花競選資源，也不替你處理尚未答應的故事。</span></button></div><div class="notice">時間用完會自動結束今天，扣生活費 80'+(s.day===4?' 與房租 700':'')+'，不足記欠款。到明天就停止。任何時候按方向鍵或「停止」可接手。</div>');}
function resumeAuto(){if(!auto)return autoConfig();close();auto.paused=false;autoStatus();autoStep();}
function autoStep(){if(!auto||auto.paused||s.phase!=='play')return;if(!s.lifeLeft){stopAuto(false);advance();return;}const c=G.routineAction(s,auto.plan);if(!c){stopAuto();return;}autoStatus();travel(c.loc,()=>{if(!auto)return;const ev=eventAt(c.loc),en=G.encounter(s,c.loc),key=c.loc;if((ev||en)&&!auto.seen.has(key)){auto.seen.add(key);auto.paused=true;place(c.loc);return;}perform(c.id,true);});}
function end(){if(s.phase==='result')return finalResult();modal('今天，就到這裡嗎？','<p>'+(s.lifeLeft?'還有 '+s.lifeLeft+' 格沒用，明天不會補回。你也可以選擇提早休息。':'今天的時間都已安排好了。')+'</p><div class="notice">今晚生活費 80'+(s.day===4?'，還有房租 700':'；明天恢復 22 精神')+'。現金不足記欠款，不動競選資源。未履行的約定會照期限結算。</div><div class="button-row"><button class="secondary-button" data-do="close">繼續走走</button><button class="primary-button" data-do="night">'+(s.day===4?'迎接開票日':'睡一覺，明天再出門')+' →</button></div>');}
function advance(){stopAuto(false);walker?.stop();const n=G.nightly(s);if(!n)return;s.position=null;walker?.setPosition({x:A.positions.home.ax*10,y:A.positions.home.ay*7});render();if(n.finished)return finalResult();modal('第 '+s.day+' 天，選舉還在繼續。',n.notes.map(t=>'<div class="callback">'+esc(t)+'</div>').join('')+'<p>今天的虛構民調：你約 '+s.polls.at(-1).percent+'%。對手與未決一起列在旁邊，這不是昨天某一句話的精確得失。</p><button class="primary-button" data-do="close">出門，重新安排行程 →</button>');}
function funds(pool){const personal=pool==='life';modal(personal?'生活帳本':'競選資源帳本','<div class="finance-grid"><div><small>'+(personal?'生活現金':'專用額度')+'</small><b>'+(personal?s.cash:s.campaign)+'</b></div><div><small>'+(personal?'未付帳單':'印刷包')+'</small><b>'+(personal?s.debt:s.supplies.print)+'</b></div><div><small>'+(personal?'工作時間格':'志工／場地')+'</small><b>'+(personal?s.workHours:s.supplies.volunteer+' / '+s.supplies.venue)+'</b></div></div><p>'+(personal?'生活費與房租只由生活現金支付，工作收入也只進這裡。':'組織支援只能用於競選，不能拿來繳房租。場地在公開說明時折抵一次成本；志工與印刷包要到地點花時間使用。公共預算不是可花的錢。')+'</p>'+s.ledger.filter(x=>x.pool===pool).map(x=>'<div class="ledger-row"><span>第 '+x.day+' 天 · '+esc(x.label)+'</span><b>'+signed(x.amount)+(x.unpaid?' ／未付 '+x.unpaid:'')+'</b></div>').join(''));}
function poll(){const p=s.polls.at(-1);modal('你、對手，與還沒決定的人。','<p>每天早晨公布同一份 n=48 的虛構自願樣本。真正的支持傾向、是否投票、抽樣結果分開保存；民調不會反過來寫成真正支持。</p>'+G.RIVALS.map(r=>'<div class="reaction"><strong>'+r.name+'：</strong>'+r.intro+'</div>').join('')+'<div class="notice">遊戲示意範圍 ±12 個百分點，不是真實統計保證。四欄四捨五入後可能不剛好等於 100%。</div>'+s.polls.map(p=>'<div class="journal-item"><small>第 '+p.day+' 天 · n=48</small><b>阿夏 '+p.percentages[0]+'% · '+G.RIVALS[0].name+' '+p.percentages[1]+'% · '+G.RIVALS[1].name+' '+p.percentages[2]+'% · 未決 '+p.percentages[3]+'%</b></div>').join('')+'<p class="modal-note">本局種子 '+s.seed+'。對手行程、天氣、插曲、抽樣與最後投票各自固定；改走路速度或重讀不會重抽。沒有真實選民或人口資料。</p>',true);}
function journal(){modal('走過的路，做過的事。',s.journal.slice().reverse().map(j=>'<div class="journal-item"><small>第 '+j.day+' 天 · '+placeName(j.loc)+'</small><b>'+esc(j.title)+'</b><p>'+esc(j.text)+'</p></div>').join('')+'<div class="button-row"><button class="secondary-button" data-do="cash">生活帳本</button><button class="secondary-button" data-do="campaign">競選帳本</button></div>',true);}
function finalResult(){const r=s.summary;if(!r)return;const title=r.winner==='you'?'阿夏當選了':r.winner==='tie'?'這一局，最高票相同':G.RIVALS.find(x=>x.id===r.winner)?.name+'這次領先';modal(title+'。','<span class="result-marker">第五天 · 選票不是道德評分</span><div class="vote-result three">'+['阿夏',...G.RIVALS.map(x=>x.name)].map((name,i)=>'<div><small>'+name+'</small><strong>'+r.tally[i]+' 票</strong></div>').join('')+'</div><p>'+r.reflection+'</p><div class="recap-grid"><div><b>生計</b><p>生活現金 '+s.cash+'，未付帳單 '+s.debt+'。競選餘額不能替你補生活缺口。</p></div><div><b>公共紀錄</b><p>留下 '+s.impact+' 份查證／整理成果，知名度 '+Math.round(s.recognition)+'。這不是已通過的政策。</p></div><div><b>承諾</b><p>更正 '+r.corrected+' 項，仍有落差 '+r.unresolved+' 項；共同約定'+({none:'未新增',pending:'未完成',kept:'已履行',missed:'失約'}[s.obligation]||'尚無')+'。設備借用約定'+(s.loan?({pending:'尚未完成',kept:'已履行',missed:'已失約'}[s.loan.status]):'未新增')+'。</p></div><div><b>自己的路線</b><p>起點：'+G.originOf(s).name+'。原有約定'+(s.originObligation?({pending:'尚未完成',kept:'已履行',missed:'已失約',released:'已公開取消'}[s.originObligation.status]):'未新增')+'。完成 '+s.choices.length+' 個故事選擇、'+s.outreach+' 次公開整理／接觸。沒有規定你一定要做完四題。</p></div></div><div class="notice">最後一份民調你約 '+r.lastPoll.percent+'%；遊戲內潛在支持平均約 '+r.latentSupport+'%；實際 '+r.total+' 人投出候選人票，另有 '+r.abstain+' 人未投或仍未決。抽樣與是否投票造成差異，不能精確歸因每一票。</div><h3>你選擇處理的事</h3>'+(s.choices.length?s.choices.map(c=>'<div class="journal-item"><small>第 '+c.day+' 天</small><b>'+esc(c.title)+'</b></div>').join(''):'<p>這一局沒有作出四類公開承諾。工作、休息與其他行動仍留在手記。</p>')+'<div class="button-row"><button class="secondary-button" data-do="journal">看完整手記</button><button class="primary-button" data-do="reset">同條件再走一條路 →</button></div>',true);}
function help(){modal('自由行動，怎麼玩？','<ol class="help-list"><li>點地圖讓它取得焦點，再用方向鍵／WASD 走路。手機可用左下方向鈕。靠近地點按 E、Enter 或互動提示。</li><li>點地點可自動走過去，不能穿過建築。走路免費；只有選行動才扣時間與資源。</li><li>每天 4 格，可以先工作、先談合作，或提早回家。四類故事自由排序，也可以不選。</li><li>組織資源附帶具體承諾；出席與是否贊成立場分開。失約不是獨立參選的懲罰。</li><li>自動日常只做你指定的普通行程，新故事會停下。方向鍵或停止可隨時接手。</li><li>同一份紀錄重複公開，新增觸及逐次減少，整理成果仍保留。實際政綱／更正變了才算新內容，換回舊內容不重置；每局最多三份不同內容有完整首次觸及。這是遊戲調整，不是真實選戰公式。</li><li>第五天三人開票。每天小樣本民調含未決，不是每句話的即時分數。</li></ol><p>完全虛構的 2.5D 小城；物種與背景不代表任何現實群體。沒有真實政治資料、投放策略或外部 LLM API。</p>');}
function reset(){stopAuto(false);modal('換一條路，再走一次？','<p>只清除本版當前進度。相同種子保留天氣、對手與抽樣條件，方便比較選擇；前版存檔仍保留。</p><div class="button-row"><button class="secondary-button" data-restart="same">同一條件重玩</button><button class="primary-button" data-restart="new">換一局小城</button></div>');}
const actions={close,start:()=>{G.start(s);render();close();},destinations,end,night:advance,journal,cash:()=>funds('life'),campaign:()=>funds('campaign'),poll,help,reset,'auto-resume':resumeAuto};document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.do){actions[b.dataset.do]?.();return;}if(b.dataset.origin&&!s.started){s=G.initial(s.seed,b.dataset.origin);render();intro();return;}if(b.dataset.decide!==undefined){const r=G.decide(s,+b.dataset.decide,b.dataset.event);if(r)result(r);return;}if(b.dataset.story)return story(b.dataset.story);if(b.dataset.act)return perform(b.dataset.act);if(b.dataset.place){if(auto)stopAuto(false);return travel(b.dataset.place);}if(b.dataset.encounter)return showEncounter(b.dataset.encounter);if(b.dataset.encChoice!==undefined){const r=G.resolveEncounter(s,b.dataset.encLoc,+b.dataset.encChoice);if(r)result(r);return;}if(b.dataset.auto){auto={plan:b.dataset.auto,paused:false,seen:new Set()};close();autoStatus();autoStep();return;}if(b.dataset.restart){const keep=b.dataset.restart==='same'?s.seed:seed();const oldOrigin=s.origin,oldSelection=s.originSelection;s=G.initial(keep,b.dataset.restart==='same'?oldOrigin:'independent');if(b.dataset.restart==='same')s.originSelection=oldSelection;walker.setPosition({x:A.positions.home.ax*10,y:A.positions.home.ay*7});render();intro();}});
$('story-btn').onclick=()=>s.phase==='result'?finalResult():near?place(near.id):destinations();$('life-btn').onclick=destinations;$('end-day-btn').onclick=end;$('journal-btn').onclick=journal;$('cash-btn').onclick=()=>funds('life');$('campaign-btn').onclick=()=>funds('campaign');$('poll-btn').onclick=poll;$('rivals-btn').onclick=poll;$('help-btn').onclick=help;$('reset-btn').onclick=reset;$('auto-btn').onclick=autoConfig;$('auto-stop').onclick=()=>stopAuto();$('location-hint').onclick=()=>near&&place(near.id);$('modal-overlay').addEventListener('click',e=>{if(e.target===$('modal-overlay'))close();});document.addEventListener('keydown',e=>{if($('modal-overlay').hidden)return;if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const f=[...$('modal').querySelectorAll('button:not(:disabled),a[href]')];if(!f.length)return;const first=f[0],last=f.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('modal'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===$('modal'))){e.preventDefault();first.focus();}}});
$('town-art').innerHTML=A.town();$('player-art').innerHTML=avatar('fox');$('mini-avatar').innerHTML=avatar('fox');walker=window.TownWalk.create({town:$('town'),avatar:$('avatar'),positions:A.positions,isPaused:()=>!s.started||!$('modal-overlay').hidden,onNear:updateNear,onInteract:id=>place(id),onMove:(p,info)=>{s.position=p;if(info.manual&&auto)stopAuto(true,true);}});if(s.position)walker.setPosition(s.position);for(const b of document.querySelectorAll('[data-dir]')){const vectors={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]};b.addEventListener('pointerdown',e=>{e.preventDefault();clearTimeout(nudgeTimer);nudgeTimer=null;if(auto)stopAuto();b.setPointerCapture?.(e.pointerId);walker.focus();walker.setDirection(...vectors[b.dataset.dir]);});b.addEventListener('click',e=>{if(e.detail!==0)return;e.preventDefault();clearTimeout(nudgeTimer);if(auto)stopAuto();walker.focus();walker.setDirection(...vectors[b.dataset.dir]);nudgeTimer=setTimeout(()=>{nudgeTimer=null;walker.setDirection(0,0);},150);});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>walker.setDirection(0,0));}
window.addEventListener('pagehide',()=>{stopAuto(false);s.position=walker.getPosition();save();});render();if(!s.started)intro();
})();
